class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        def toIdx(c: str) -> int:
            return ord(c) - ord('a')
        cnt = [0] * 26

        for c in p:
            cnt[toIdx(c)] += 1

        ans = []
        l = 0
        for r, c in enumerate(s):
            cnt[toIdx(c)] -= 1
            while cnt[toIdx(c)] < 0:  # If number of characters `c` is more than our expectation
                cnt[toIdx(s[l])] += 1  # Slide left until cnt[c] == 0
                l += 1
            if r - l + 1 == len(p):  #  If we already filled enough `p.length()` chars
                ans.append(l)  # Add left index `l` to our result

        return ans
